function buildScene(SDK, data) {
  const c = data.concept;
  const y = 250, x0 = 60, x1 = 600, sc = (x1 - x0) / 80;           // the road: 0 → 80 m
  SDK.shape("line", { x1: x0, y1: y, x2: x1, y2: y, stroke: "var(--ink)", "stroke-width": 3 });
  for (let m = 0; m <= 80; m += 10) {
    SDK.shape("line", { x1: x0 + m * sc, y1: y - 6, x2: x0 + m * sc, y2: y + 6, stroke: "var(--ink)", "stroke-width": 2 });
    SDK.text(x0 + m * sc, y + 24, m, { size: 11, ltr: true });
  }
  SDK.text(x1 + 18, y + 24, "m", { size: 11, ltr: true });
  const car = SDK.character(c.id, { x: x0, y: y - 46, size: 70, label: false });
  const formula = SDK.text(320, 40, "", { size: 18, ltr: true });
  let a = 2, dots = [];
  const clear = () => { dots.forEach(d => d.remove()); dots = []; };
  const place = (t) => { const d = 0.5 * a * t * t; car.g.setAttribute("transform", "translate(" + (x0 + Math.min(d, 80) * sc) + " " + (y - 46) + ")"); car.x = x0 + Math.min(d, 80) * sc; return d; };
  SDK.slider({ label: "التسارع a (م/ث²)", min: 1, max: 4, step: 0.5, value: 2 }, v => {
    a = v; clear(); place(0); formula.textContent = "d = ½ a t²   ·   a = " + a + " m/s²";
    SDK.caption("اختار التسارع واكبس «انطلق»: شوف المسافة كل ثانية.");
  });
  SDK.button("انطلق ▶", () => {
    clear(); place(0); let shown = 0;
    SDK.tween(4000, t => {
      const time = t * 6, d = place(time);
      for (; shown < Math.floor(time) && shown < 6; shown++) {
        const s = shown + 1, ds = 0.5 * a * s * s;
        if (ds <= 80) { dots.push(SDK.shape("circle", { cx: x0 + ds * sc, cy: y - 8, r: 5, fill: "var(--warn)", stroke: "none" })); dots.push(SDK.text(x0 + ds * sc, y - 18, s + "s", { size: 11, ltr: true })); }
      }
    }).then(() => {
      car.say("كل ثانية المسافة أكبر من اللي قبلها: السرعة عم تزيد.");
      SDK.caption("النقاط بتتباعد: هاد هو «" + c.name + "» — " + c.meaning);
      SDK.done("watched");
    });
  });
}
